# region: sift
def sift(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: render
def render(xs, floor_=3):
    return [v for v in xs if v > floor_]

# region: shape
def shape(xs, floor_=3):
    return [v for v in xs if v >= floor_]

# region: fold
def fold(xs, offset=1):
    return [v + offset for v in xs]

# region: intake
def intake(xs, cut=8):
    lo = [v for v in xs if v < cut]
    hi = [v for v in xs if v >= cut]
    return {'n': len(xs), 'lo': len(lo), 'hi': len(hi)}

# region: emit
def emit(summary, bar=2):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return emit(intake(fold(shape(render(sift(raw))))))

